// CORE-6161: the validation assistant on screens without the validation form
// (PO matching, accounting): sidebar, width, pop-out and one chat per document.
// The page provides `docId` plus `current_sidebar` / `toggleSideBar` from useSidebarPanel().
import { defineComponent } from 'vue';
import type { AssistantScreen } from 'src/services/validationAssistant/validationAssistantService';
import { validationAssistantWidth } from 'src/utils/validationAssistantWidth';
import { loadConversation, saveConversation } from 'src/utils/validationAssistant/conversationStore';
import { assistantWindowPath, validationScreenPath } from 'src/utils/validationAssistant/paths';

export const VALIDATION_ASSISTANT_SIDEBAR = 'validation_assistant';

type PanelConversationApi = {
  exportConversation?: () => unknown;
  importConversation?: (state: unknown) => void;
};

export function validationAssistantHostMixin(screen: AssistantScreen) {
  return defineComponent({
    data() {
      return {
        assistantScreen: screen,
        validationAssistantWindow: null as Window | null,
        compactAssistant: false,
      };
    },

    computed: {
      assistantDocId(): string {
        const self = this as unknown as { docId?: string };
        return String(self.docId || this.$route.params.id || '');
      },
      assistantOpen(): boolean {
        return (this as unknown as { current_sidebar: string }).current_sidebar === VALIDATION_ASSISTANT_SIDEBAR;
      },
      // a dragged assistant width overrides the 25vw sidebar class
      assistantSidebarStyle(): Record<string, string> | undefined {
        const width = validationAssistantWidth.width;
        if (!this.assistantOpen || !width) return undefined;
        return { width: `${width}px`, maxWidth: `${width}px` };
      },
      assistantRightSectionStyle(): Record<string, string> | undefined {
        const width = validationAssistantWidth.width;
        if (!this.assistantOpen || !width) return undefined;
        return { width: `calc(100% - ${width}px)` };
      },
    },

    mounted() {
      // the pop-out window reaches its opener through this reference
      (<any>window).ValidationAssistantHostView = this;
    },

    beforeUnmount() {
      this.closeValidationAssistantWindow();
      if ((<any>window).ValidationAssistantHostView === this) {
        (<any>window).ValidationAssistantHostView = null;
      }
    },

    methods: {
      sidebarToggle(name: string) {
        (this as unknown as { toggleSideBar: (name: string) => void }).toggleSideBar(name);
      },
      toggleValidationAssistant() {
        this.sidebarToggle(VALIDATION_ASSISTANT_SIDEBAR);
      },
      openValidationAssistant() {
        if (!this.assistantOpen) this.sidebarToggle(VALIDATION_ASSISTANT_SIDEBAR);
      },
      closeValidationAssistant() {
        if (this.assistantOpen) this.sidebarToggle(VALIDATION_ASSISTANT_SIDEBAR);
      },
      assistantPanel(): PanelConversationApi | null {
        return (this.$refs.validationAssistantPanel as PanelConversationApi | undefined) || null;
      },
      /** The field is on the validation screen: go there, open the assistant, focus it. */
      openValidationAtField(field?: string | null) {
        const query: Record<string, string> = { open: 'validation-assistant' };
        if (field) query.focus = field;
        void this.$router.push({ path: validationScreenPath(this.assistantDocId), query });
      },
      // Opener API for the pop-out window; there is no blocker board off the validation screen.
      getValidationBlockersSnapshot(): null {
        return null;
      },
      getValidationAssistantConversation(): unknown {
        return this.assistantPanel()?.exportConversation?.() ?? loadConversation(this.assistantDocId);
      },
      syncValidationAssistantConversation(state: unknown) {
        saveConversation(this.assistantDocId, state);
        this.assistantPanel()?.importConversation?.(state);
      },
      restoreValidationAssistantConversation(state: unknown) {
        this.compactAssistant = false;
        saveConversation(this.assistantDocId, state);
        this.openValidationAssistant();
        this.$nextTick(() => this.assistantPanel()?.importConversation?.(state));
      },
      onValidationAssistantWindowClosed() {
        this.validationAssistantWindow = null;
        this.compactAssistant = false;
      },
      closeValidationAssistantWindow() {
        if (this.validationAssistantWindow && !this.validationAssistantWindow.closed) {
          this.validationAssistantWindow.close();
        }
        this.validationAssistantWindow = null;
        this.compactAssistant = false;
      },
      openValidationAssistantWindow() {
        if (this.validationAssistantWindow && !this.validationAssistantWindow.closed) {
          this.validationAssistantWindow.focus();
          return;
        }
        const route = this.$router.resolve({
          path: assistantWindowPath(this.assistantDocId),
          query: { screen: this.assistantScreen },
        });
        const width = 820;
        const height = 960;
        const left = Math.max(0, Math.round((window.screen.width - width) / 2));
        const top = Math.max(0, Math.round((window.screen.height - height) / 2));
        const assistantWindow = window.open(
          route.href,
          'validation_assistant',
          `width=${width},height=${height},left=${left},top=${top}`,
        );
        // a blocked popup returns null: offer the sidebar instead of silence
        if (!assistantWindow) {
          void this.$q
            .dialog({
              title: this.$t('validation_assistant_title'),
              message: this.$t('validation_assistant_popup_blocked'),
              cancel: true,
              ok: {
                label: this.$t('validation_assistant_popup_blocked_sidebar'),
                flat: true,
                color: 'primary',
              },
              persistent: true,
            })
            .onOk(() => this.openValidationAssistant());
          return;
        }
        this.validationAssistantWindow = assistantWindow;
        assistantWindow.focus();
        const conversation = this.assistantPanel()?.exportConversation?.();
        if (conversation) saveConversation(this.assistantDocId, conversation);
        this.compactAssistant = true;
        this.closeValidationAssistant();
      },
    },
  });
}
